<template>
  <div
    :style="boxStyle"
    ref="box"
    @click="onBoxClick"
    class="point-marker-tool"
  >
    <div
      v-for="(marker, index) in markers"
      :key="index"
      :class="'marker'"
      :style="markerStyle(marker.position.x, marker.position.y)"
      @click.stop="removeMarker(index)"
    >
      <div class="marker-icon"></div>
      <div class="marker-title" v-if="marker.sceneTitle">{{ marker.sceneTitle }}</div>
    </div>
  </div>
</template>
  
  <script>
export default {
  name: 'PointMarkerTool',
  props: {
    backgroundImage: {
      type: String,
      required: true,
    },
    markerImage: {
      type: String,
      default: require('@/assets/default/marker.png'),
    },
    maxWidth: {
      type: Number,
      default: 480,
    },
    limit: {
      type: Number,
      default: 1, // 0: 不限制，1：只能添加一个，2：只能添加两个，以此类推
    },
  },
  data() {
    return {
      markers: [], // 存放标记的数组
      scaleW: 1,
      scaleH: 1,
      maxHeight: 0,
      enableMarker: false,
      currentScene: null,
    }
  },
  computed: {
    boxStyle() {
      return {
        position: 'relative',
        width: '600px',
        height: '400px',
        backgroundImage: `url(${this.backgroundImage})`,
        backgroundSize: 'cover',
        border: '1px solid #000',
        cursor: this.enabled ? `url(${this.markerImage}), auto` : 'default',
      }
    },
    enabled() {
      return (
        this.enableMarker &&
        (this.limit === 0 || this.markers.length < this.limit)
      )
    },
  },
  mounted() {
    this.loadImage()
  },
  methods: {
    setMarkers(markers) {
      this.markers = markers
    },
    enable() {
      this.enableMarker = true
    },
    disable() {
      this.enableMarker = false
    },
    remove() {
      this.enableMarker = false
      this.markers = []
      this.currentScene = null
      this.scaleH = 1
      this.scaleW = 1
      this.maxHeight = 0
    },
    sceneMarker(scene) {
      this.enable()
      this.currentScene = scene
    },
    loadImage() {
      const img = new Image()
      img.src = this.backgroundImage

      img.onload = () => {
        const imgWidth = img.width
        const imgHeight = img.height
        const aspectRatio = imgWidth / imgHeight
        const maxWidth = this.maxWidth
        const maxHeight = maxWidth * aspectRatio
        this.maxHeight = maxHeight
        let containerWidth, containerHeight

        if (aspectRatio > 1) {
          containerWidth = Math.min(imgWidth, maxWidth)
          containerHeight = containerWidth / aspectRatio
        } else {
          containerHeight = Math.min(imgHeight, maxHeight)
          containerWidth = containerHeight * aspectRatio
        }
        this.$refs.box.style.width = containerWidth + 'px'
        this.$refs.box.style.height = containerHeight + 'px'
        this.scaleW = Number((containerWidth / imgWidth).toFixed(2))
        this.scaleH = Number((containerHeight / imgHeight).toFixed(2))
        this.markers.map((marker) => {
          marker.x = marker.x * this.scaleW
          marker.y = marker.y * this.scaleH
        })
        this.$emit('image-loaded', {
          width: containerWidth,
          height: containerHeight,
          scaleW: this.scaleW,
          scaleH: this.scaleH,
        })
      }
    },
    onBoxClick(event) {
      const x = event.offsetX
      const y = event.offsetY
      this.addMarker(x, y)
    },
    addMarker(x, y) {
      if (!this.enabled) {
        return
      }
      if (this.limit === 1 && this.markers.length > 0) {
        this.markers = []
      }
      const position = { x, y }
      const scale = { scaleW: this.scaleW, scaleH: this.scaleH }
      const point = {
        sceneId: this.currentScene ? this.currentScene.sceneId : 0,
        sceneTitle: this.currentScene ? this.currentScene.sceneTitle : '',
        position: position,
        scale: scale,
      }
      this.markers.push(point)
      this.$emit('marker-added', point)
    },
    removeSceneMarker(scene) {
        this.markers = this.markers.filter(
          (marker) => marker.sceneId !== scene.sceneId
        )
    },
    removeMarker(index) {
      this.markers.splice(index, 1)
      this.$emit('marker-removed', {
        node: this.markers[index],
      })
    },
    markerStyle(x, y) {
      return {
        position: 'absolute',
        //   width: '20px',
        //   height: '20px',
        left: `${x}px`,
        top: `${y}px`,
      }
    },
  },
}
</script>
  
  <style scoped>
.marker {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.marker-icon {
  width: 20px;
  height: 20px;
  background-image: url("@/assets/default/marker.png"); /* 替换为你的 marker 图 */
  background-size: contain;
  background-repeat: no-repeat;
  cursor: pointer;
}

.marker-title {
  margin-top: 4px;
  max-width: 60px; /* 根据需求调整宽度 */
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-align: center;
  font-size: 12px;
  color: #fff;
}
</style>
  